const messages: Record<Language, Record<TranslationKey, string>> = {
  "zh-CN": zh,
  en,
  fr,
  de,
};

function supportedLanguage(value: string): Language | null {
  const language = value.trim().toLowerCase().split(/[_\-.@]/, 1)[0];
  if (language === "zh") return "zh-CN";
  if (language === "en" || language === "fr" || language === "de") return language;
  return null;
}

export function hasSavedLanguagePreference() {
  const saved = window.localStorage.getItem("intel-nuc.language");
  return saved === "zh-CN" || saved === "en" || saved === "fr" || saved === "de";
}

function detectLanguage(): Language {
  const saved = window.localStorage.getItem("intel-nuc.language");
  if (saved === "zh-CN" || saved === "en" || saved === "fr" || saved === "de") {
    return saved;
  }
  const browserLanguages =
    window.navigator.languages?.length > 0
      ? window.navigator.languages
      : [window.navigator.language];
  for (const browserLanguage of browserLanguages) {
    const supported = supportedLanguage(browserLanguage);
    if (supported) return supported;
  }
  return "en";
}

function format(template: string, variables?: Variables) {
  if (!variables) return template;
  return Object.entries(variables).reduce(
    (text, [name, value]) => text.split(`{${name}}`).join(String(value)),
    template,
  );
}

type I18nValue = {
  language: Language;
  setLanguage: (language: Language) => void;
  t: (key: TranslationKey, variables?: Variables) => string;
};

const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>(detectLanguage);
  const setLanguage = useCallback((next: Language) => {
    window.localStorage.setItem("intel-nuc.language", next);
    setLanguageState(next);
  }, []);
  const t = useCallback(
    (key: TranslationKey, variables?: Variables) =>
      format(messages[language][key], variables),
    [language],
  );

  useEffect(() => {
    document.documentElement.lang = language;
  }, [language]);

  const value = useMemo(
    () => ({ language, setLanguage, t }),
    [language, setLanguage, t],
  );
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  const value = useContext(I18nContext);
  if (!value) throw new Error("I18nProvider is missing");
  return value;
}

export const languageOptions: Array<{ value: Language; labelKey: TranslationKey }> = [
  { value: "zh-CN", labelKey: "language.zh" },
  { value: "en", labelKey: "language.en" },
  { value: "fr", labelKey: "language.fr" },
  { value: "de", labelKey: "language.de" },
];
